# Nibfin job-started hook of a collaborator's Runner. Generated by gh nibfin
# runner add; do not edit. The runner runs it before any step of a Job (the
# slot's .env sets ACTIONS_RUNNER_HOOK_JOB_STARTED to it) and fails the Job
# when it exits non-zero. It only lets official Nibfin Jobs for the Runner's
# owner run: check.mjs, beside it, makes the checks with the runner's own
# Node.js. It writes nothing but a temporary directory, which it removes.

refuse() {
  printf 'Nibfin hook: refused: %s\n' "$1"
  exit 1
}

# The hook's directory: from the script's own path, else from the variable
# the runner found it by (the slot's .env).
self=${BASH_SOURCE:-$0}
case $self in
/*/job-started.sh) ;;
*) self=${ACTIONS_RUNNER_HOOK_JOB_STARTED:-} ;;
esac
case $self in
/*/job-started.sh) ;;
*) refuse "the hook does not know its own location. Run gh nibfin runner add again." ;;
esac
hook=${self%/*}

sha=${GITHUB_WORKFLOW_SHA:-}
case $sha in
*[!0-9a-f]* | '') refuse "GITHUB_WORKFLOW_SHA is not a commit SHA" ;;
esac
if [ ${#sha} -ne 40 ] && [ ${#sha} -ne 64 ]; then
  refuse "GITHUB_WORKFLOW_SHA is not a full commit SHA"
fi

dir=${NIBFIN_RUNNER_DIR:-}
case $dir in
/*) ;;
*) refuse "NIBFIN_RUNNER_DIR is not set to the Runner's directory. Run gh nibfin runner remove, then gh nibfin runner add." ;;
esac

tmp=$(mktemp -d) || refuse "cannot create a temporary directory"
trap 'rm -rf "$tmp"' EXIT
cd "$tmp" || refuse "cannot enter $tmp"

private= owner= name= key=
while IFS= read -r line || [ -n "$line" ]; do
  case $line in
  owner=*) owner=${line#owner=} ;;
  name=*) name=${line#name=} ;;
  private=*) private=${line#private=} ;;
  deploy-key=*) key=${line#deploy-key=} ;;
  esac
done <"$hook/config" || refuse "cannot read $hook/config. Run gh nibfin runner add again."

# The highest Node.js the runner ships.
node= best=0
for n in "$dir"/externals/node*/bin/node; do
  v=${n#"$dir"/externals/node}
  v=${v%/bin/node}
  case $v in '' | *[!0-9]*) continue ;; esac
  if [ -x "$n" ] && [ "$v" -gt "$best" ]; then node=$n best=$v; fi
done
if [ -z "$node" ] || [ "$best" -lt 20 ]; then
  refuse "no Node.js 20 or later under $dir/externals. Run gh nibfin runner remove, then gh nibfin runner add."
fi

mkdir fetched
if [ "$private" = 1 ]; then
  case $owner/$name in
  *[!A-Za-z0-9._/-]* | /* | */) refuse "the hook config names no repository. Run gh nibfin runner add again." ;;
  esac
  case $key$hook in
  *"'"*) refuse "the deploy key path has a quote. Run gh nibfin runner remove, then gh nibfin runner add." ;;
  esac
  [ -f "$key" ] || refuse "the deploy key $key is missing. Run gh nibfin runner remove, then gh nibfin runner add."
  command -v git >/dev/null 2>&1 || refuse "git is not installed on this host. Install git and the OpenSSH client."
  export HOME="$tmp" GIT_CONFIG_NOSYSTEM=1 GIT_CONFIG_GLOBAL=/dev/null GIT_TERMINAL_PROMPT=0
  export GIT_SSH_COMMAND="ssh -F /dev/null -i '$key' -o IdentitiesOnly=yes -o IdentityAgent=none -o BatchMode=yes -o UserKnownHostsFile='$hook/known_hosts' -o StrictHostKeyChecking=yes"
  git init -q repo || refuse "cannot create a git repository in $tmp"
  if ! err=$(timeout 120 git -C repo fetch -q --depth=1 --no-tags "git@github.com:$owner/$name.git" "$sha" 2>&1); then
    refuse "cannot read $owner/$name at $sha with the deploy key: $err. If the deploy key was removed on GitHub, run gh nibfin runner remove, then gh nibfin runner add."
  fi
  for f in nibfin-shared-runner.yml nibfin-job.yml; do
    if ! err=$(git -C repo show "FETCH_HEAD:.github/workflows/$f" 2>&1 >"fetched/$f"); then
      refuse "$owner/$name@$sha has no .github/workflows/$f: $err. The Owner runs gh nibfin upgrade."
    fi
  done
fi

env -i PATH=/usr/local/bin:/usr/bin:/bin HOME="$tmp" LANG=C.UTF-8 \
  GITHUB_WORKFLOW_REF="${GITHUB_WORKFLOW_REF:-}" GITHUB_WORKFLOW_SHA="$sha" \
  GITHUB_EVENT_NAME="${GITHUB_EVENT_NAME:-}" GITHUB_EVENT_PATH="${GITHUB_EVENT_PATH:-}" \
  "$node" "$hook/check.mjs" "$hook" "$tmp/fetched"
